const row = $input.item.json;
return {
  json: {
    name: row['Name'],
    phone: row['Phone No'],
    category: row['Complaint Category'],
    urgency: row['Severity'] || 'Not Urgent',
    description: row['Description'],
    timestamp: new Date().toISOString()
  }
};

const output = $json.output;
const match = output.match(/BOOKING_DATA:\s*(\{.*\})/);
const customerMessage = output.split('BOOKING_DATA:')[0].trim();

let bookingData = null;
if (match) {
  bookingData = JSON.parse(match[1]);
}

return {
  json: {
    customer_message: customerMessage,
    booking: bookingData,
    session_id: $('Webhook').item.json.body.sessionId,
    timestamp: new Date().toISOString()
  }
};
